import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { createFptTts, FPT_VOICES } from '../src/lib/fpt-tts.mjs';

// Protocol-faithful FPT.AI stub: POST returns {error:0, async:url}; the URL
// 404s once (still rendering) then serves a real MP3 generated by ffmpeg.
function makeStub(dir) {
  const mp3 = path.join(dir, 'voice.mp3');
  execFileSync('ffmpeg', ['-v', 'error', '-y', '-f', 'lavfi', '-i', 'sine=frequency=440:duration=1.2', '-codec:a', 'libmp3lame', mp3]);
  const bytes = fs.readFileSync(mp3);
  let gets = 0;
  const calls = [];
  const fetchImpl = async (url, opts = {}) => {
    calls.push({ url: String(url), method: opts.method || 'GET', headers: opts.headers || {} });
    if (String(url).endsWith('/hmi/tts/v5')) {
      assert.equal(opts.headers['api-key'], 'test-key-123456');
      return { ok: true, status: 200, json: async () => ({ error: 0, async: 'https://file.fpt.ai/tts/abc123.mp3', request_id: 'req-1', message: 'Successful.' }) };
    }
    if (String(url) === 'https://file.fpt.ai/tts/abc123.mp3') {
      gets++;
      if (gets < 2) return { ok: false, status: 404, arrayBuffer: async () => new ArrayBuffer(0) };
      return { ok: true, status: 200, arrayBuffer: async () => bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength) };
    }
    throw new Error('unexpected url ' + url);
  };
  return { fetchImpl, calls };
}

test('FPT synthesize: posts, waits for render, downloads, converts to WAV', async () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'fpt-tts-'));
  const { fetchImpl, calls } = makeStub(dir);
  const tts = createFptTts({ apiKey: 'test-key-123456', fetchImpl, sleep: async () => {} });
  assert.equal(tts.configured(), true);
  const out = path.join(dir, 'line.wav');
  const result = await tts.synthesize({ text: 'Xin chào Việt Nam', voice: 'lannhi', language: 'vi', output: out });
  assert.equal(result.provider, 'fpt');
  assert.equal(result.voice, 'lannhi');
  assert.ok(fs.existsSync(out) && fs.statSync(out).size > 1000);
  const probe = JSON.parse(execFileSync('ffprobe', ['-v', 'quiet', '-print_format', 'json', '-show_format', out]).toString());
  assert.ok(Number(probe.format.duration) > 0.8);
  assert.equal(calls[0].method, 'POST');
});

test('FPT synthesize blocks honestly: no key, wrong language, foreign audio host', async () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'fpt-tts-'));
  const noKey = createFptTts({ apiKey: '', fetchImpl: async () => { throw new Error('must not be called'); } });
  await assert.rejects(() => noKey.synthesize({ text: 'chào', language: 'vi', output: path.join(dir, 'a.wav') }), e => e.code === 'BLOCKED_TTS');
  const { fetchImpl } = makeStub(dir);
  const tts = createFptTts({ apiKey: 'test-key-123456', fetchImpl, sleep: async () => {} });
  await assert.rejects(() => tts.synthesize({ text: 'hello', language: 'en', output: path.join(dir, 'b.wav') }), e => e.code === 'BLOCKED_DUB_VOICE');
  const evil = createFptTts({ apiKey: 'test-key-123456', sleep: async () => {}, fetchImpl: async (url, opts = {}) => {
    if (String(url).endsWith('/hmi/tts/v5')) return { ok: true, status: 200, json: async () => ({ error: 0, async: 'https://evil.example.com/x.mp3', request_id: 'r' }) };
    throw new Error('must not download');
  } });
  await assert.rejects(() => evil.synthesize({ text: 'chào', language: 'vi', output: path.join(dir, 'c.wav') }), e => e.code === 'TTS_DOWNLOAD');
  assert.ok(FPT_VOICES.length >= 5);
});
